import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ugc-creator-finder`,heroTitle:`Find your perfect UGC creators in minutes`,heroSubtitle:`Perplexity Computer finds creators already making content in your category, compares fit and pricing signals, and packages the shortlist with outreach notes.`,inputUrlCta:`Find my creators`,inputUrlPlaceholder:`yourproductpage.com`,inputUrlPrefill:`Go to {url} and build a UGC creator shortlist for this product. (1) Research creators already making content in this category across relevant social platforms and creator marketplaces. (2) Evaluate content fit, audience alignment, engagement signals, and likely pricing. (3) Prioritize 25 creators most worth contacting first. (4) Collect portfolio links and contact paths where available. (5) Deliver a spreadsheet-style creator list with estimated pricing notes and a brief template tailored to this product.`,heroOverlaySteps:[`Researching creators already making content in your category`,`Comparing audience fit, engagement signals, and pricing clues`,`Ranking the creators most worth contacting first`,`Creator shortlist with portfolio links and outreach notes ready to use`],generatingSteps:[`Visiting {url} to understand the product, category, and creator profile to target`,`Designing an agent to source creators and benchmark fit across multiple platforms`,`Configuring ranking logic for relevance, engagement, and likely pricing`,`Packaging the work into a spreadsheet-style creator list with outreach notes`],featureSectionTitle:`From product page to creator shortlist`,featureCardTitles:[`Connects to your creator workflow`,`Outputs your team can recruit from`],featureCardDescriptions:[`Computer splits the work into creator sourcing, fit analysis, pricing research, and list packaging so scouting is less fragmented and more repeatable.`,`Sheets, Notion, CRM notes, and creative planning tools can stay connected so your team can move from research into outreach fast.`,`Ranked creators. Portfolio links. Pricing notes. Brief templates. Computer gives your team a shortlist that is ready for recruitment.`],capabilitySectionTitle:`Your creator scout, on demand`,capabilitySectionSubtitle:`Paste your product page, step away, and come back to creators worth contacting first.`,capabilityCards:[{title:`Creator Discovery`,description:`Computer can identify creators already publishing in your category so you start with people who naturally fit the product.`},{title:`Fit & Pricing Research`,description:`Computer can compare engagement signals, style fit, and likely pricing so you can prioritize creators more confidently.`},{title:`Recruiting Notes`,description:`Computer can package contact paths, portfolio links, and product-specific brief notes so outreach starts with better context.`},{title:`Connect Your Tools`,description:`Computer can organize the shortlist across Sheets, Notion, and planning tools so recruiting stays coordinated across the team.`},{title:`Priority Ranking`,description:`Computer can rank the creators most worth pursuing first based on fit, content quality, and likely efficiency.`},{title:`Refresh the Roster`,description:`Computer can refresh the list later and add emerging creators as the category evolves.`}]});export{t as default};
